package com.valorantx.presentation.controller;
import com.valorantx.business.service.UsuarioService; import com.valorantx.presentation.dto.*; import jakarta.validation.Valid; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/usuarios") @CrossOrigin(origins="http://localhost:5173") public class UsuarioController { private final UsuarioService service; public UsuarioController(UsuarioService service){this.service=service;} @PostMapping("/registro") public ResponseEntity<?> registrar(@Valid @RequestBody RegistroRequest r){try{return ResponseEntity.ok(Map.of("mensaje",service.registrar(r)));}catch(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("mensaje",e.getMessage()));}} @PostMapping("/login") public ResponseEntity<?> login(@Valid @RequestBody LoginRequest r){if(service.iniciarSesion(r))return ResponseEntity.ok(Map.of("mensaje","Inicio de sesión exitoso"));return ResponseEntity.status(401).body(Map.of("mensaje","Usuario o contraseña incorrectos"));} }
